import React, { useState, useRef } from "react";
import { useNavigate, useParams } from "react-router-dom";

const OrarSali = ({ onRoomClick }) => {
  const navigate = useNavigate();
  const { etaj } = useParams(); // Preia etajul din URL
  const [activeDropdown, setActiveDropdown] = useState(null);
  const dropdownRefs = useRef([]);

  // Listă cu etaje și săli
  const etaje = [
    {
      label: "Parter",
      icon: "🏢",
      sali: ["C2", "C112", "C210"],
    },
    {
      label: "Etaj 1",
      icon: "🧱",
      sali: ["C308", "C309"],
    },
    {
      label: "Etaj 2",
      icon: "🏬",
      sali: ["C401", "C403", "C405", "C409", "C411", "C412", "C413"],
    },
    {
      label: "Etaj 7",
      icon: "🌇",
      sali: ["C901", "C903"],
    },
  ];

  const toggleDropdown = (index, e) => {
    e.stopPropagation();
    setActiveDropdown((prev) => (prev === index ? null : index));
    const selectedEtaj = etaje[index].label;
    navigate(`/app/orar/sali/${selectedEtaj}`); // Actualizează URL-ul cu etajul selectat
  };

  const handleSalaSelect = (sala) => {
    if (etaj) {
      navigate(`/app/orar/sali/${etaj}/${sala}`); // Include etajul și sala în URL
      onRoomClick(sala); // Apelează funcția prop pentru a seta sala selectată
    } else {
      console.error("Etajul nu este selectat!");
    }
  };

  return (
    <div className="orar-sali-container">
      <div className="orar-buttons">
        {etaje.map((etaj, index) => (
          <div
            className="dropdown-container"
            key={index}
            ref={(el) => (dropdownRefs.current[index] = el)}
          >
            <button
              className="orar-button"
              onClick={(e) => toggleDropdown(index, e)}
            >
              <span className="icon">{etaj.icon}</span>
              {etaj.label}
            </button>

            {activeDropdown === index && (
              <div className="dropdown-menu">
                {etaj.sali.map((sala, i) => (
                  <button
                    className="dropdown-item"
                    key={i}
                    onClick={() => handleSalaSelect(sala)}
                  >
                    {sala}
                  </button>
                ))}
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

export default OrarSali;
